import Foundation
import SwiftParser
@testable import SwiftStatsCore
import Testing

/// SwiftInferProperties' suggestions linked to the property tests that
/// check them (PRD §7.11): a generated file carrying the identity, a
/// `@CheckProperty` macro, and the heuristic, which needs a property test
/// outside generated files whose target depends on the function's module.
@Suite("Property test links")
struct PropertyTestLinkTests {
    private typealias Row = PropertyHarness.Row

    /// The library's second file: `clamped()` on line 3 carries the macro,
    /// `widened()` is on line 7, the operators `+` and prefix `~` on lines
    /// 11 and 15.
    private static let gauge = """
        public struct Gauge: Equatable {
            @CheckProperty(.idempotent)
            public func clamped() -> Gauge {
                self
            }

            public func widened() -> Gauge {
                self
            }

            public static func + (lhs: Gauge, rhs: Gauge) -> Gauge {
                lhs
            }

            public static prefix func ~ (gauge: Gauge) -> Gauge {
                gauge
            }
        }
        """

    /// The generated test for `doubled()`'s suggestion.
    private static let stub = """
        // Auto-generated by `swift-infer discover --interactive` — do not edit.
        // Source: Sources/Core/Values.swift:4
        // Suggestion identity: 0x00000000000000A1
        // Template: idempotence
        import PropertyLawKit
        import Testing
        @testable import Core

        @Test func doubledIsIdempotent() async {
            let backend = SwiftPropertyBasedBackend()
            _ = await backend.check(trials: 100, seed: nil, sample: { Money(cents: 1) }, property: { money in
                money.doubled().doubled() == money.doubled().doubled()
            })
            _ = Money(cents: 1).widened()
        }
        """

    /// Hand-written tests in the target depending on the library.
    private static let coreTests = """
        // Suggestion identity: 0x00000000000000b9
        import PropertyBased
        import Testing
        @testable import Core

        @Test func doublingTwice() async {
            await propertyCheck(input: Gen.int()) { value in
                #expect(Money(cents: value).doubled().cents == value * 2)
            }
        }

        @Test func decodes() async {
            await propertyCheck(input: Gen.int()) { value in
                #expect(Money.decoded(String(value)).cents == value)
            }
        }

        @Test func reduces() {
            #expect(reduce(1, 2) == 3)
        }

        @Test func addsInEitherOrder() async {
            await propertyCheck(input: Gen.int()) { value in
                #expect(Gauge() + Gauge() == Gauge() + Gauge())
            }
        }

        @Test func invertsTwice() {
            #expect(~(~Gauge()) == Gauge())
        }
        """

    /// The package's files: the harness library, the gauge, a production
    /// file whose header names an identity, the generated test, and test
    /// targets depending on the library, on nothing, and on the tool.
    private static let files = [
        "Sources/Core/Values.swift": PropertyHarness.values,
        "Sources/Core/Gauge.swift": gauge,
        "Sources/Core/Stub.swift": "// Suggestion identity: 0x00000000000000B9\nfunc stubbed() {}\n",
        "Sources/Tool/main.swift": "print(\"hi\")\n",
        "Tests/CoreTests/Generated/SwiftInfer/idempotence/DoubledTests.swift": stub,
        "Tests/CoreTests/MoneyTests.swift": coreTests,
        "Tests/OtherTests/OtherTests.swift": """
            import PropertyBased
            import Testing

            @Test func reducesAnything() async {
                await propertyCheck(input: Gen.int()) { value in
                    #expect(reduce(value, 0) == value)
                }
            }
            """,
        "Tests/ToolTests/ToolTests.swift": """
            import PropertyBased
            import Testing

            @Test func widens() async {
                await propertyCheck(input: Gen.int()) { value in
                    #expect(Gauge().widened() == Gauge().widened())
                }
            }
            """
    ]

    /// The targets: the tool depends on the library, as do the library's
    /// tests; the tool's tests reach the library through the tool.
    private static let targets = [
        DescribedTarget(
            name: "Core",
            type: "library",
            moduleType: "SwiftTarget",
            path: "Sources/Core",
            sources: ["Gauge.swift", "Stub.swift", "Values.swift"]
        ),
        DescribedTarget(
            name: "CoreTests",
            type: "test",
            moduleType: "SwiftTarget",
            path: "Tests/CoreTests",
            sources: ["Generated/SwiftInfer/idempotence/DoubledTests.swift", "MoneyTests.swift"],
            targetDependencies: ["Core"]
        ),
        DescribedTarget(
            name: "OtherTests",
            type: "test",
            moduleType: "SwiftTarget",
            path: "Tests/OtherTests",
            sources: ["OtherTests.swift"]
        ),
        DescribedTarget(
            name: "Tool",
            type: "executable",
            moduleType: "SwiftTarget",
            path: "Sources/Tool",
            sources: ["main.swift"],
            targetDependencies: ["Core"]
        ),
        DescribedTarget(
            name: "ToolTests",
            type: "test",
            moduleType: "SwiftTarget",
            path: "Tests/ToolTests",
            sources: ["ToolTests.swift"],
            targetDependencies: ["Tool"]
        )
    ]

    /// The library's files, as the tool writes them.
    private static let values = "@ROOT@/Sources/Core/Values.swift"
    /// The gauge's file, as the tool writes it.
    private static let gaugeFile = "@ROOT@/Sources/Core/Gauge.swift"

    /// One row per link to find, and rows no link reaches.
    private static let rows = [
        Row(identity: "0x00000000000000A1", location: "\(values):4"),
        Row(
            identity: "0x00000000000000A4",
            location: "\(values):12",
            template: "round-trip",
            function: "encoded()",
            extra: ", \"secondaryFunctionName\": \"decoded(_:)\""
        ),
        Row(identity: "0x00000000000000B9", location: "\(values):12", function: "encoded()"),
        Row(identity: "0x00000000000000C1", location: "\(values):29", function: "reduce(_:_:)"),
        Row(identity: "0x00000000000000E1", location: "\(gaugeFile):3", function: "clamped()"),
        Row(identity: "0x00000000000000E2", location: "\(gaugeFile):7", function: "widened()"),
        Row(
            identity: "0x00000000000000E3",
            location: "\(gaugeFile):11",
            template: "commutativity",
            function: "+(lhs:rhs:)"
        ),
        Row(identity: "0x00000000000000E4", location: "\(gaugeFile):15", template: "involution", function: "~(gauge:)")
    ]

    @Test("""
        a generated file's identity, a macro on the function, or a property test calling the function or its \
        partner from a target that depends on its module links a suggestion; nothing else does
        """)
    func links() throws {
        let package = try TemporaryPackage(Self.files, targets: Self.targets)
        defer { package.remove() }
        let tool = try FakeTool.makeIndexer(
            indexes: ["Core": PropertyHarness.index(Self.rows), "Tool": PropertyHarness.emptyIndex],
            errors: [:],
            statuses: [:],
            delays: [:]
        )
        defer { PropertyHarness.remove(tool) }
        let report = try package.scan(tools: PropertyHarness.locator(tool))
        let properties = try #require(report.properties)
        let byIdentity = Dictionary(uniqueKeysWithValues: properties.candidates.map { ($0.identity, $0) })
        let testKey = { (name: String) in
            try #require(report.tests.first { $0.key.contains("func \(name)()") }).key
        }

        #expect(byIdentity.mapValues { $0.testedBy?.rawValue ?? "none" } == [
            "0x00000000000000A1": "generated",
            "0x00000000000000A4": "handwritten",
            "0x00000000000000B9": "none",
            "0x00000000000000C1": "none",
            "0x00000000000000E1": "macro",
            "0x00000000000000E2": "handwritten",
            "0x00000000000000E3": "handwritten",
            // `~` is used only by a test that isn't a property test.
            "0x00000000000000E4": "none"
        ])
        #expect(byIdentity["0x00000000000000A1"]?.testKeys == [try testKey("doubledIsIdempotent")])
        // Through the partner, `decoded(_:)`.
        #expect(byIdentity["0x00000000000000A4"]?.testKeys == [try testKey("decodes")])
        #expect(byIdentity["0x00000000000000E1"]?.testKeys.isEmpty == true)
        // The generated test also calls `widened()`, but only hand-written tests count.
        #expect(byIdentity["0x00000000000000E2"]?.testKeys == [try testKey("widens")])
        #expect(byIdentity["0x00000000000000B9"]?.testKeys.isEmpty == true)
        // Through the infix use of `+`.
        #expect(byIdentity["0x00000000000000E3"]?.testKeys == [try testKey("addsInEitherOrder")])
        #expect(report.tests.first { $0.key.contains("func reducesAnything()") }?.kind == .property)
    }

    @Test("a function's base name drops its labels and type, and an operator keeps every character")
    func baseNames() {
        #expect(PropertyTestLinks.baseName("decoded(_:)") == "decoded")
        #expect(PropertyTestLinks.baseName("Money.decoded(_:)") == "decoded")
        #expect(PropertyTestLinks.baseName("encoded") == "encoded")
        #expect(PropertyTestLinks.baseName("+(lhs:rhs:)") == "+")
        #expect(PropertyTestLinks.baseName("..<(_:_:)") == "..<")
        #expect(PropertyTestLinks.baseName("Money.+(lhs:rhs:)") == "+")
        #expect(PropertyTestLinks.baseName("Money...<(_:_:)") == "..<")
        #expect(PropertyTestLinks.baseName("!(aggregate:)") == "!")
    }

    @Test("prefix, infix and postfix operators in a property test's body count as its callees")
    func operatorCallees() {
        let scan = TestBodyScan(viewMode: .sourceAccurate)
        let source = "let total = -left + right.value!\nlet flag = !(total < limit)\nlet tail = total...\n"
        scan.walk(Parser.parse(source: source))

        // The force unwrap is no operator.
        #expect(scan.callees == ["-", "+", "<", "!", "..."])
    }

    @Test("an identity counts only on a comment line of its own before the first token, in uppercase hex")
    func stubIdentities() {
        let tree = { (source: String) in PropertyTestLinks.stubIdentities(in: Parser.parse(source: source)) }

        #expect(tree("// Suggestion identity: 0x00000000000000A1  \nimport Testing\n") == ["0x00000000000000A1"])
        #expect(tree("// Suggestion identity: 0x00000000000000a1\nimport Testing\n").isEmpty)
        #expect(tree("// Suggestion identity: 0x00000000000000A\nimport Testing\n").isEmpty)
        #expect(tree("// Suggestion identity:  0x00000000000000A1\nimport Testing\n").isEmpty)
        #expect(tree("/* Suggestion identity: 0x00000000000000A1 */\nimport Testing\n").isEmpty)
        #expect(tree("import Testing\n// Suggestion identity: 0x00000000000000A1\nlet value = 1\n").isEmpty)
    }
}
